<?php
namespace Tests\Feature;
use App\Models\ComplianceSetting;use App\Models\Employee;use App\Models\PayrollRun;use App\Models\Payslip;use App\Models\Tenant;use App\Services\PayrollComparisonService;use Illuminate\Support\Str;use Tests\TestCase;
class PayrollComparisonTest extends TestCase { public function test_previous_regular_run_comparison_marks_entered_missing_and_deltas():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Compare '.Str::random(4)]);try{tenancy()->initialize($tenant);$setting=ComplianceSetting::create(['version_label'=>'cmp','effective_date'=>'2026-01-01','settings'=>[]]);$a=Employee::create(['name'=>'A','national_id'=>'C-A','hire_date'=>'2026-01-01','salary'=>'500.000','status'=>'active']);$b=Employee::create(['name'=>'B','national_id'=>'C-B','hire_date'=>'2026-01-01','salary'=>'500.000','status'=>'active']);$c=Employee::create(['name'=>'C','national_id'=>'C-C','hire_date'=>'2026-02-01','salary'=>'500.000','status'=>'active']);$prev=PayrollRun::create(['month'=>8,'year'=>2026,'run_type'=>'regular','sequence'=>1,'status'=>'approved','compliance_setting_id'=>$setting->id,'locked_at'=>now()]);Payslip::create(['payroll_run_id'=>$prev->id,'employee_id'=>$a->id,'gross_salary'=>'500.000','net_salary'=>'450.000','calculation_snapshot'=>[]]);Payslip::create(['payroll_run_id'=>$prev->id,'employee_id'=>$b->id,'gross_salary'=>'500.000','net_salary'=>'400.000','calculation_snapshot'=>[]]);$cur=PayrollRun::create(['month'=>9,'year'=>2026,'run_type'=>'regular','sequence'=>1,'status'=>'calculated','compliance_setting_id'=>$setting->id]);Payslip::create(['payroll_run_id'=>$cur->id,'employee_id'=>$a->id,'gross_salary'=>'550.000','net_salary'=>'500.000','calculation_snapshot'=>[]]);Payslip::create(['payroll_run_id'=>$cur->id,'employee_id'=>$c->id,'gross_salary'=>'500.000','net_salary'=>'440.000','calculation_snapshot'=>[]]);$r=app(PayrollComparisonService::class)->compare($cur);$this->assertSame($prev->id,$r['previous']['id']);$states=collect($r['employees'])->pluck('state','employee_id');$this->assertSame('continuing',$states[$a->id]);$this->assertSame('missing',$states[$b->id]);$this->assertSame('entered',$states[$c->id]);$this->assertSame('50.000',$r['totals']['net_salary']['delta']);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
